entries[42183] = { ["name"] = "Muster: Abgründige Tasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine abgründige Tasche näht.\nBenötigt Schneiderei von Nordend (60)\nBenötigt Ritter der Schwarzen Klinge\n- Respektvoll\nVerkaufspreis:\nAbgründige Tasche\nWird beim Anlegen gebunden\n22 Platz Tasche\nVerkaufspreis:\nBenötigt Schwarztuch (4), Zaubertuch (2), Eterniumfaden" }
entries[42184] = { ["name"] = "Muster: Eisige Tasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine eisige Tasche näht.\nDas Nähen einer eisigen Tasche ist so schwierig, dass sich ein Schneider nur alle 7 Tage daran versuchen sollte.\nBenötigt Schneiderei von Nordend (70)\nBenötigt Die Söhne Hodirs\n- Ehrfürchtig\nVerkaufspreis:\nEisige Tasche\nWird beim Anlegen gebunden\n22 Platz Tasche\nVerkaufspreis:\nBenötigt Mondgespinst (4), Schwarztuch (4), Eterniumfaden" }
entries[42185] = { ["name"] = "Muster: Mysteriöse Tasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine mysteriöse Tasche näht.\nBenötigt Schneiderei von Nordend (65)\nBenötigt Der Wyrmruhpakt\n- Respektvoll\nVerkaufspreis:\nMysteriöse Tasche\nWird beim Anlegen gebunden\n32 Platz Verzauberertasche\nVerkaufspreis:\nBenötigt Zaubertuch (4), Mondgespinst (2), Eterniumfaden" }
entries[42186] = { ["name"] = "Muster: Froststofftasche", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man eine Froststofftasche näht.\nBenötigt Schneiderei von Nordend (35)\nVerkaufspreis:\nFroststofftasche\nWird beim Anlegen gebunden\n20 Platz Tasche\nVerkaufspreis:\nBenötigt Magieerfüllter Froststoffballen (6), Eterniumfaden (2)" }
entries[42187] = { ["name"] = "Muster: Glänzender Zauberfaden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man glänzenden Zauberfaden herstellt.\nBenötigt Schneiderei von Nordend (55)\nBenötigt Argentumkreuzzug\n- Ehrfürchtig\nVerkaufspreis:\nGlänzender Zauberfaden\nBenutzen: Bestickt Hosen dauerhaft mit einem Zauberfaden, der die Zaubermacht um 3 und die Vielseitigkeit um 3 erhöht.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Äonenleben (4), Vereiste Spinnenseide (4), Gefrorene Kugel" }
entries[42188] = { ["name"] = "Muster: Saphirfarbener Zauberfaden", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man saphirfarbenen Zauberfaden herstellt.\nBenötigt Schneiderei von Nordend (55)\nBenötigt Kirin Tor\n- Ehrfürchtig\nVerkaufspreis:\nSaphirfarbener Zauberfaden\nBenutzen: Bestickt Hosen dauerhaft mit einem Zauberfaden, der die Zaubermacht um 4 und die Ausdauer um 3 erhöht.\n\nDurch diese Verzauberung wird der Gegenstand seelengebunden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nVerkaufspreis:\nBenötigt Äonenfeuer (4), Vereiste Spinnenseide (4), Gefrorene Kugel" }
