entries[42190] = { ["name"] = "Muster: Todesfrostumhang", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Todesfrostumhang näht.\nBenötigt Schneiderei von Nordend (45)\nVerkaufspreis:\nTodesfrostumhang\nWird beim Anlegen gebunden\nRücken\n3 Rüstung\n+2 Intelligenz\nErhöht Eure kritische Trefferwertung um + 3.\nErhöht Eure Tempowertung um + 4.\nVerkaufspreis:\nBenötigt Magieerfüllter Froststoffballen (5), Äonenfeuer (6), Äonenschatten (4), Sirenenträne , Gefrorene Kugel" }
