entries[42984] = { ["name"] = "Geputzte Eisenfederschultern", ["text"] = "Wird an Kriegsmeute gebunden\nSchulter Leder\n1 Rüstung\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 26225 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%." }
entries[42985] = { ["name"] = "Zerlumpter Mantel der Furcht", ["text"] = "Wird an Kriegsmeute gebunden\nSchulter Stoff\n1 Rüstung\nOrnat der sagenhaften Abenteurer (0/7)\nErbstückbrustrüstung\nErbstückhelm\nErbstückschultern\nErbstückumhang\nErbstückbeinrüstung\nErbstückkette\nErbstückring\n(2) Set : Verringert den Verbrauch des Ruhebonus um 30%.\n(3) Set : Erhöht in Außengebieten, in normalen Dungeons und auf Schlachtfeldern Eure Regeneration außerhalb des Kampfes.\n(5) Set : Ein Stufenaufstieg löst eine 'Explosion des Wissens' aus, die Gegnern in der Nähe 26225 Heiligschaden zufügt und Eure Hauptwert 2 Min. lang um 40% erhöht. Das Besiegen von Gegnern verlängert diesen Effekt um bis zu zusätzlich 2 Min.\n(6) Set : Verringert den Verbrauch des Ruhebonus um zusätzlich 30%." }
entries[42986] = { ["name"] = "Die RG-GG", ["text"] = "Tausendwinter\nEinzigartig (5)\nBenutzen: Feuert eine Hitzesuchrakete ab, die versucht, feindliche Panzer zu verfolgen.\nGranatwerfer für raketengetriebene Goblingranaten werden beim Tod fallengelassen.\n\"Ausschließlich für Militärzwecke.\"" }
entries[42987] = { ["name"] = "Dunkelmond-Karte: Grandeur", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+4 Stärke\nAnlegen: Bei hervorgerufener Heilung oder verursachtem Schaden besteht eine Chance, dass 'Grandeur' ausgelöst wird. Dieser Effekt erhöht Eure Stärke, Eure Beweglichkeit oder Eure Intelligenz 15 Sek. lang um 15 . Es wird stets Euer höchster Wert gewählt. (Procchance: 35%, 45s Abklingzeit)\nVerkaufspreis:" }
entries[42988] = { ["name"] = "Dunkelmond-Karte: Illusion", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+4 Intelligenz\nBenutzen: Absorbiert 6 Sek. lang 7 Schaden. Wenn der Schild auf irgendeine Art entfernt wird, gewinnt Ihr 77 Mana zurück. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[42989] = { ["name"] = "Dunkelmond-Karte: Berserker!", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+ 7 Vielseitigkeit\nAnlegen: Ihr habt eine Chance, zum Berserker zu werden, wenn Ihr im Kampf Schaden verursacht oder erleidet. Euer kritischer Trefferwert erhöht sich 12 Sek. lang um 3 . Der Effekt ist bis zu 3-mal stapelbar. (Procchance: 50%)\nVerkaufspreis:" }
entries[42990] = { ["name"] = "Dunkelmond-Karte: Tod", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 6.\nAnlegen: Jedes Mal, wenn Ihr Schaden verursacht, besteht eine Chance, zusätzliche 10 Schattenschaden zu verursachen. (Procchance: 15%, 45s Abklingzeit)\nVerkaufspreis:" }
